import * as E from './engine.js';
import {factionEmblem} from './heraldry.js';
import {worldTiles}from'./world.js';
import {expeditionWorld}from'./procedural.js';
const counts=units=>Object.entries(units.reduce((a,u)=>(a[u.type]=(a[u.type]||0)+1,a),{}));
const resourceName=k=>({gold:'oro',wood:'madera',supply:'petróleo',metal:'acero'}[k]);
function preview(target){const tiles=worldTiles(expeditionWorld(target));return'<svg class="island-preview" viewBox="0 0 100 100" role="img" aria-label="Costa de la isla, río y paso central"><rect width="100" height="100" fill="#367d9b"/>'+tiles.flatMap((row,y)=>row.map((v,x)=>v?'<rect x="'+x*5+'" y="'+y*5+'" width="5" height="5" fill="'+({desert:'#c5aa70',tundra:'#bfd0ce',volcanic:'#7c7475',marsh:'#749578'}[target.biome]||'#8faa65')+'"/>':'')).join('')+'<rect x="55" y="50" width="5" height="5" fill="#b79d76"/><circle cx="22" cy="51" r="2.5" fill="#bce6ff"/><rect x="73" y="48" width="4" height="4" fill="#e59779"/></svg>';}
function factionInfo(s,t){const f=t?.faction&&E.factionById(t.faction),r=f&&E.relation(s,f.id);return f?'<p class="frontier-faction"><img src="'+factionEmblem(f.id)+'" alt="Emblema de '+f.name+'" width="42" height="48"><b>'+f.name+'</b> · '+E.RACES[f.race].name+' · '+(r?.status==='war'?'En guerra':r?.status==='ally'?'Aliados':'Neutral')+'</p><button class="wide" data-action="diplomacy">Hablar con los clanes</button>':'';}
export function frontierPanel(s,h,filters){const{panelHead,esc,fmt,clock}=h,f=E.frontier(s),season=E.seasonAt(s.time),owned=f.colonies.filter(c=>c.owned).length;return panelHead('EXPANSIÓN · RIVALES DE IA','Más allá de Aurora')+'<button class="wide" data-action="territory-section" data-type="home">← Sectores de mi base</button><div class="frontier-calendar"><strong>'+season.name+' · Año '+season.year+'</strong><span>Día '+season.day+' · cambio en '+clock(season.remaining)+'</span></div><p>Islas procedurales de 100 × 100, seis biomas y niebla de guerra. Cada reconocimiento crea una costa y una base nuevas. Las estaciones cambian el terreno, la producción colonial y el viaje marítimo. Los clanes pueden comerciar, aliarse o entrar en guerra contigo.</p><div class="frontier-filters"><label>Defensa rival<select id="frontier-level">'+Array.from({length:10},(_,i)=>'<option value="'+(i+1)+'" '+(filters.level===i+1?'selected':'')+'>'+(i+1)+' · '+(i<2?'Puesto básico':i<6?'Base militar':'Fortaleza avanzada')+'</option>').join('')+'</select></label><label>Bioma<select id="frontier-biome"><option value="any">Cualquiera</option>'+Object.entries(E.BIOMES).map(([id,b])=>'<option value="'+id+'" '+(filters.biome===id?'selected':'')+'>'+b.name+'</option>').join('')+'</select></label></div><button class="primary wide" data-action="island-search">Buscar isla · '+E.searchCost(filters.level).gold+' oro</button>'+(f.target?'<article class="quest-card">'+preview(f.target)+'<h3>'+esc(f.target.name)+'</h3>'+factionInfo(s,f.target)+'<p>Defensa '+f.target.level+' / 10 · '+f.target.distance+' km · '+resourceName(E.BIOMES[f.target.biome].resource)+'</p><button class="wide" data-action="island-briefing">Preparar desembarco</button></article>':'')+'<div class="section-label">TUS COLONIAS · '+owned+' / 3</div>'+(f.colonies.length?f.colonies.map(c=>'<article class="quest-card"><h3>'+esc(c.name)+'</h3><p>'+(!c.owned?'Ocupada por la IA':('Puesto nivel '+c.level+' · '+c.garrison.length+' tropas · '+fmt(c.stock[E.BIOMES[c.target.biome].resource])+' '+resourceName(E.BIOMES[c.target.biome].resource)))+'</p>'+(c.warning?'<p class="warning">Ataque de la IA en '+clock(c.warning.ends-s.time)+'.</p>':'')+'<button data-action="colony-open" data-id="'+c.id+'">'+(c.owned?'Gestionar puesto':'Reconquistar')+'</button></article>').join(''):'<p class="tiny">Destruye el mando y las defensas de una isla para fundar tu primer puesto de extracción.</p>')+'<div class="section-label">RUTAS DE SUMINISTRO</div><p class="tiny">Las colonias almacenan su producción. Construye terminales, despacha carga y recógela al llegar. La carga que no cabe en tu base se conserva.</p>'+f.shipments.map(t=>'<article class="quest-card"><h3>'+esc(t.name)+'</h3><p>'+(t.mode==='sea'?'Transporte naval':'Transporte aéreo')+' · '+(t.arrived?'En el almacén de llegada':clock(t.ends-s.time)+' en ruta')+' · '+fmt(Object.values(t.cargo).reduce((a,b)=>a+b,0))+' materiales</p><div class="progress"><span style="width:'+Math.min(100,100*(s.time-t.started)/(t.ends-t.started))+'%"></span></div></article>').join('')+(f.shipments.some(t=>t.arrived)?'<button class="wide primary" data-action="shipment-claim">Recoger entregas</button>':'')+'<div class="section-label">ÚLTIMOS INFORMES</div>'+f.reports.slice(0,6).map(r=>'<p class="tiny"><b>'+esc(r.name)+'</b> · '+esc(r.text)+'</p>').join('')+'<p class="tiny">Partida individual. Multijugador, cuentas y funciones sociales pausados.</p>';}
export function expeditionBriefing(s,h,target=E.frontier(s).target){
 const{head,esc,fmt}=h;if(!target)return head('RECONOCIMIENTO','Busca una isla primero.');
 const owned=E.frontier(s).colonies.filter(c=>c.owned).length,peaceful=E.allied(s,target.faction),neutral=E.civilization(s).race&&target.faction&&!E.atWar(s,target.faction)&&!peaceful;
 const intro=head((peaceful?'ACUERDO TERRITORIAL':'DESEMBARCO')+' · DEFENSA '+target.level+'/10',esc(target.name))+preview(target)+factionInfo(s,target)+'<p>'+E.BIOMES[target.biome].name+' · '+target.distance+' km. Río interior y puente transitable. El puesto necesitará una ruta de suministros marítima o aérea.</p>';
 if(peaceful)return intro+'<p>Sus habitantes son aliados. El acuerdo permite establecer un puesto sin combatir, sin bajas y sin premio de saqueo. Conservas tus '+s.army.length+' tropas.</p><p>Acuerdo: 250 oro, 180 madera y 100 petróleo. Ocupará una de tus tres plazas de colonia. Después podrás asignar guarnición, mejorar el puesto y transportar su producción.</p><button class="primary wide" data-action="island-settle" '+(owned>=3?'disabled':'')+'>Fundar puesto por acuerdo · '+owned+'/3</button>';
 return intro+(neutral?'<p class="warning">Este clan es neutral. Puedes negociar una alianza o declarar la guerra desde Hablar con los clanes. Sus territorios no se atacan mientras haya paz.</p>':'')+'<p>Tienes '+s.army.length+' tropas disponibles. Despliega en azul, explora bajo la niebla y destruye el mando y todas las defensas armadas antes de 15 minutos. Las bajas son permanentes. Retirarse conserva reservas y supervivientes.</p><p>Botín de victoria: '+fmt(250+target.level*300)+' oro, '+fmt(150+target.level*120)+' madera, '+fmt(100+target.level*100)+' petróleo y '+fmt(80+target.level*100)+' acero. El excedente se reserva en Metas.</p><div class="action-row"><button class="primary" data-action="island-start" data-type="conquer" '+(owned>=3||neutral?'disabled':'')+'>Conquistar '+owned+'/3</button><button data-action="island-start" data-type="raid" '+(neutral?'disabled':'')+'>Saquear y regresar</button></div><p class="tiny">Conquistar funda un puesto nivel 1. Máximo tres colonias. El astillero se desbloquea con mando 3. Sólo participan facciones NPC locales.</p>';
}
export function colonyDetails(s,id,h){const{head,esc,fmt,clock}=h,c=E.frontier(s).colonies.find(c=>c.id===id);if(!c)return head('COLONIA','Puesto no disponible.');if(!c.owned)return head('OCUPACIÓN ENEMIGA',esc(c.name))+'<p>La IA conquistó este puesto. Tu base principal sigue siendo tuya. Prepara otro ejército para recuperarlo.</p><button class="primary wide" data-action="island-start" data-id="'+c.id+'" data-type="conquer">Reconquistar</button><button class="wide danger" data-action="colony-abandon-dialog" data-id="'+c.id+'">Olvidar puesto</button>';
 const primary=E.BIOMES[c.target.biome].resource,armies=counts(s.army),stationed=counts(c.garrison);return head('PUESTO NIVEL '+c.level,esc(c.name))+'<div class="action-row"><button data-action="colony-visit" data-id="'+c.id+'">Ver isla y tropas</button>'+(c.warning?'<button class="primary" data-action="colony-defend" data-id="'+c.id+'">Dirigir defensa</button>':'')+'</div><p>'+E.BIOMES[c.target.biome].name+' · producción de '+fmt(E.extractionRate(s,c))+' '+resourceName(primary)+'/hora y un ingreso secundario de oro. Depósito de '+fmt(E.colonyCapacity(c))+' por recurso. Hasta ocho horas de producción al volver.</p><div class="result-stats">'+E.RESOURCE_KEYS.map(k=>'<div><b>'+fmt(c.stock[k])+'</b><span>'+resourceName(k)+'</span></div>').join('')+'</div><div class="section-label">DESARROLLO</div>'+(c.job?'<p class="warning">Mejorando · '+clock(c.job.ends-s.time)+'</p>':'<p>Mejora: '+250*c.level+' oro, '+150*c.level+' madera, '+100*c.level+' acero. Tiempo: '+clock(120*c.level)+'. Requiere mando principal nivel '+(c.level+1)+'.</p><button data-action="colony-upgrade" data-id="'+c.id+'" '+(c.level>=Math.min(10,E.hqLevel(s))?'disabled':'')+'>Mejorar puesto</button>')+'<div class="section-label">GUARNICIÓN · '+c.garrison.length+' / 32</div><p>Fuerza defensiva '+fmt(E.colonyPower(c))+' frente a '+E.attackPower(c)+' del siguiente ataque. '+(c.warning?'Ataque en '+clock(c.warning.ends-s.time):'Próximo reconocimiento en '+clock(c.nextAttack-s.time))+'. Los plazos enemigos se detienen al cerrar el juego.</p><p class="tiny">Cada traslado consume 10 petróleo por punto de población. Las unidades conservan su salud y siguen ocupando población global. Los heridos regresan al hospital de tu base para curarse.</p>'+stationed.map(([type,n])=>'<div class="stat-row"><span>'+esc(E.UNITS[type].name)+' × '+n+'</span><button data-action="garrison-recall" data-id="'+c.id+'" data-type="'+type+'">Retirar 1</button></div>').join('')+(armies.length?'<p class="tiny">Refuerzos disponibles en tu base:</p>':'<p class="tiny">Entrena tropas o retira una guarnición de otro puesto.</p>')+armies.map(([type,n])=>'<div class="stat-row"><span>'+esc(E.UNITS[type].name)+' × '+n+'</span><button data-action="garrison-send" data-id="'+c.id+'" data-type="'+type+'" '+(c.garrison.length>=32?'disabled':'')+'>Enviar 1</button></div>').join('')+'<div class="section-label">TRANSPORTE</div>'+(c.route?'<p>Ruta '+(c.route.mode==='sea'?'marítima · 1.500 materiales/viaje':'aérea · 750 materiales/viaje')+'. Combustible por envío: '+(c.route.mode==='sea'?25:65)+' petróleo.</p><button class="wide" data-action="shipment-send" data-id="'+c.id+'">Despachar carga disponible</button>':c.routeJob?'<p class="warning">Estudio y terminales en construcción · '+clock(c.routeJob.ends-s.time)+'</p>':'<p>Estudio y terminales: 150 oro, 180 madera y 80 petróleo · 90 s. Mar: requiere astillero. Aire: requiere aeródromo.</p><div class="action-row"><button data-action="route-build" data-id="'+c.id+'" data-type="sea" '+(!E.routeQuote(s,c,'sea').ok?'disabled':'')+'>Establecer vía marítima</button><button data-action="route-build" data-id="'+c.id+'" data-type="air" '+(!E.routeQuote(s,c,'air').ok?'disabled':'')+'>Establecer vía aérea</button></div>')+'<p class="tiny">La guarnición intenta defender automáticamente si no diriges el combate. Una derrota puede perder el puesto y su depósito.</p><button class="danger wide" data-action="colony-abandon-dialog" data-id="'+c.id+'">Abandonar puesto</button>';}
